   0 /**
   1  * RAG Health Check API Endpoint
   2  * 
   3  * Returns the health status of the RAG system including:
   4  * - Vector store connectivity
   5  * - Ollama embedding service
   6  * - Collection statistics
   7  */
   8 
   9 import { NextRequest, NextResponse } from 'next/server';
  10 import { getVectorStore } from '@/lib/rag/vector-store';
  11 import { RAGConfig, validateRAGConfig } from '@/lib/rag/config';
  12 
  13 export async function GET(_request: NextRequest) {
  14   try {
  15     const checks = {
  16       config: { status: 'unknown' as 'ok' | 'error', details: {} as any },
  17       vectorStore: { status: 'unknown' as 'ok' | 'error', details: {} as any },
  18       ollama: { status: 'unknown' as 'ok' | 'error', details: {} as any },
  19     };
  20 
  21     // 1. Validate configuration
  22     const configValidation = validateRAGConfig();
  23     checks.config.status = configValidation.valid ? 'ok' : 'error';
  24     checks.config.details = {
  25       provider: RAGConfig.vectorStore.provider,
  26       dimension: RAGConfig.vectorStore.dimension,
  27       errors: configValidation.errors,
  28     };
  29 
  30     // 2. Check vector store
  31     try {
  32       const vectorStore = getVectorStore();
  33       
  34       // Check if it's Qdrant with healthCheck method
  35       if (typeof vectorStore.healthCheck === 'function') {
  36         const isHealthy = await vectorStore.healthCheck();
  37         checks.vectorStore.status = isHealthy ? 'ok' : 'error';
  38         
  39         if (isHealthy) {
  40           const stats = await vectorStore.getStats();
  41           checks.vectorStore.details = {
  42             type: 'qdrant',
  43             url: RAGConfig.qdrant.url,
  44             collection: RAGConfig.qdrant.collectionName,
  45             totalChunks: stats.totalChunks,
  46             vectorDimension: stats.vectorDimension,
  47           };
  48         } else {
  49           checks.vectorStore.details = { error: 'Health check failed' };
  50         }
  51       } else {
  52         // In-memory store
  53         const size = typeof vectorStore.size === 'function' 
  54           ? await vectorStore.size() 
  55           : vectorStore.size();
  56         
  57         checks.vectorStore.status = 'ok';
  58         checks.vectorStore.details = {
  59           type: 'memory',
  60           totalChunks: size,
  61         };
  62       }
  63     } catch (error) {
  64       checks.vectorStore.status = 'error';
  65       checks.vectorStore.details = {
  66         error: error instanceof Error ? error.message : 'Unknown error',
  67       };
  68     }
  69 
  70     // 3. Check Ollama embedding service
  71     try {
  72       const response = await fetch(`${RAGConfig.ollama.baseUrl}/api/tags`, {
  73         method: 'GET',
  74         signal: AbortSignal.timeout(5000), // 5 second timeout
  75       });
  76 
  77       if (response.ok) {
  78         const data = await response.json();
  79         const hasEmbeddingModel = data.models?.some(
  80           (m: any) => m.name.includes(RAGConfig.ollama.embeddingModel)
  81         );
  82 
  83         checks.ollama.status = hasEmbeddingModel ? 'ok' : 'error';
  84         checks.ollama.details = {
  85           url: RAGConfig.ollama.baseUrl,
  86           model: RAGConfig.ollama.embeddingModel,
  87           modelAvailable: hasEmbeddingModel,
  88           availableModels: data.models?.map((m: any) => m.name).slice(0, 5) || [],
  89         };
  90       } else {
  91         checks.ollama.status = 'error';
  92         checks.ollama.details = {
  93           error: `HTTP ${response.status}: ${response.statusText}`,
  94         };
  95       }
  96     } catch (error) {
  97       checks.ollama.status = 'error';
  98       checks.ollama.details = {
  99         error: error instanceof Error ? error.message : 'Connection failed',
 100         url: RAGConfig.ollama.baseUrl,
 101       };
 102     }
 103 
 104     // Determine overall status
 105     const allOk = Object.values(checks).every(check => check.status === 'ok');
 106     const overallStatus = allOk ? 'healthy' : 'degraded';
 107 
 108     return NextResponse.json({
 109       status: overallStatus,
 110       timestamp: new Date().toISOString(),
 111       checks,
 112       config: {
 113         provider: RAGConfig.vectorStore.provider,
 114         embeddingModel: RAGConfig.ollama.embeddingModel,
 115         vectorDimension: RAGConfig.vectorStore.dimension,
 116       },
 117     });
 118 
 119   } catch (error) {
 120     console.error('Health check error:', error);
 121     
 122     return NextResponse.json(
 123       {
 124         status: 'error',
 125         timestamp: new Date().toISOString(),
 126         error: error instanceof Error ? error.message : 'Unknown error',
 127       },
 128       { status: 500 }
 129     );
 130   }
 131 }
