   9 export async function GET() {
  10     try {
  11         let stylesCollection = adminDb.collection('templates').doc('docx').collection('styles');
  12         let snapshot = await stylesCollection.get();
  13 
  14         // Lazy seeding: If no templates exist, populate them from the default config.
  15         if (snapshot.empty) {
  16             let batch = adminDb.batch();
  17             (Object.keys(defaultTemplates) as DocxTemplateKey []).forEach(key => {
  18                 let template = defaultTemplates[key];
  19                 let docRef = stylesCollection.doc(key);
  20                 batch.set(docRef, { ...template, id: key, createdAt: new Date().toISOString() });
  21             });
  22             await batch.commit();
  23             snapshot = await stylesCollection.get(); // Re-fetch after seeding
  24         }
  25 
  26         let templates: { [key: string]: any } = {};
  27         snapshot.docs.forEach((doc) => {
  28             templates[doc.id] = doc.data();
  29         });
  30 
  31         return createApiResponse(templates, 200);
  32     } catch (error) {
  33         return handleApiError(error);
  34     }
  35 }
  36 
  37 
  38 const createDocxTemplateSchema = z.object({
  39   id: z.string().min(3, "ID must be at least 3 characters").regex(/^[a-z0-9-]+$/, "ID can only contain lowercase letters, numbers, and hyphens."),
  40   name: z.string().min(1, "Name is required"),
  41   description: z.string().min(1, "Description is required"),
  42 });
  43 
  44 export const POST = withAuth(async ({ request }) => {
  45     try {
  46         let body = await request.json();
  47         let validation = createDocxTemplateSchema.safeParse(body);
  48         if(!validation.success) {
  49             return handleApiError(validation.error);
  50         }
  51 
  52         let { id, name, description } = validation.data;
  53 
  54         // Create a new template based on the 'modern' default
  55         let newTemplateData = {
  56             name,
  57             description,
  58             styles: defaultTemplates.modern.styles,
  59             imageUrl: 'https://placehold.co/400x565.png',
  60             dataAiHint: 'document modern',
  61         };
  62 
  63         let newTemplate = await createGenerativeTemplate('docx', id, newTemplateData);
  64 
  65         return createApiResponse(newTemplate, 201);
  66     } catch (error) {
  67         return handleApiError(error);
  68     }
  69 }, { requireAdmin: true });
  70 
