  31         if (t.status === 'verified') {
  32             totalVerified += t.price;
  33         }
  34     });
  35 
  36     markdown += `\n## Summary\n\n`;
  37     markdown += `- **Total Transactions:** ${transactions.length}\n`;
  38     markdown += `- **Total Verified Revenue:** $${totalVerified.toFixed(2)}\n`;
