  31   const handleSendRequest = async () => {
  32     setIsLoading(true);
  33     setError(null);
  34     setResponse(null);
  35 
  36     try {
  37       let token: string | undefined;
  38       if (endpoint.auth !== 'public' && firebaseUser) {
  39         token = await firebaseUser.getIdToken();
  40       } else if (endpoint.auth !== 'public') {
  41         throw new Error('Authentication required for this endpoint.');
  42       }
  43       
  44       const headers: HeadersInit = {
  45         'Content-Type': 'application/json',
  46       };
  47       if (token) {
  48         headers['Authorization'] = `Bearer ${token}`;
  49       }
  50 
  51       const res = await fetch(endpoint.path, {
  52         method: endpoint.method,
  53         headers,
  54         body: endpoint.method !== 'GET' && body ? body : undefined,
  55       });
  56 
  57       const data = await res.json();
  58 
  59       if (!res.ok) {
  60         throw new Error(data.message || 'Request failed');
  61       }
  62 
  63       setResponse(data);
  64 
  65     } catch (err: any) {
  66       setError(err.message);
  67       toast({
