  70         variant: 'destructive',
  71       });
  72     } finally {
  73       setIsLoading(false);
  74     }
  75   };
  76 
  77   return (
  78     <div className="border rounded-lg p-4 space-y-4 bg-muted/30">
  79       <h4 className="font-semibold text-sm flex items-center gap-2">
  80         <Send className="w-4 h-4" />
  81         Live API Tester
