  91             rows={5}
  92             className="font-mono text-xs"
  93             placeholder="Enter JSON request body..."
  94             disabled={isLoading}
  95           />
  96         </div>
  97       )}
  98 
  99       <Button onClick={handleSendRequest} disabled={isLoading} className="w-full">
