 106           <Label>Response</Label>
 107           <ScrollArea className="h-64 rounded-md border p-2 bg-background">
 108             {error ? (
 109               <div className="p-4 text-center text-destructive">
 110                 <ServerCrash className="mx-auto h-8 w-8 mb-2" />
 111                 <p>{error}</p>
 112               </div>
