   6 import { useMutation, type UseMutationOptions } from '@tanstack/react-query';
   7 
   8 /**
   9  * A generic hook for calling AI writing tools.
  10  * It handles authentication, loading state, error handling, and credit deduction automatically.
  11  *
  12  * @param endpoint The specific API endpoint for the tool (e.g., '/api/writing-tools/summarize').
  13  * @param options Optional React Query mutation options.
  14  * @returns A React Query mutation object.
  15  */
  16 export function useWritingTool<TData = unknown, TVariables = any>(
  17   endpoint: string,
  18   options?: Omit<UseMutationOptions<TData, Error, TVariables>, 'mutationFn'>
  19 ) {
  20   const { firebaseUser, refetchUser } = useAuth();
  21   const toolName = endpoint.split('/').pop() || '';
  22 
  23   return useMutation<TData, Error, TVariables>({
  24     mutationFn: async (data: TVariables) => {
  25       // Use apiService which handles auth and errors
  26       return apiService({
  27         endpoint, // The full endpoint is passed in now
  28         method: 'POST',
  29         data: { ...data, flow: toolName }, // Still useful to send flow name for logging
  30         firebaseUser,
  31       });
  32     },
  33     onSuccess: (data, variables, context) => {
  34       // Refetch user profile to update credit count in the UI
  35       refetchUser();
  36       if (options?.onSuccess) {
  37         // @ts-expect-error - Type mismatch with TanStack Query callback signature
  38         options.onSuccess(data, variables, context);
  39       }
  40     },
  41     onError: (error: Error, variables, context) => {
  42       toast({
  43         title: 'An Error Occurred',
  44         description: error.message,
  45         variant: 'destructive',
  46       });
  47       if (options?.onError) {
  48         // @ts-expect-error - Type mismatch with TanStack Query callback signature
  49         options.onError(error, variables, context);
  50       }
  51     },
  52     // Spread any additional options passed in
  53     ...options,
  54   });
  55 }
