  29             if (!firebaseUser) throw new Error("User not authenticated");
  30             const token = await firebaseUser.getIdToken();
  31             return updateFeatureApi(variables, token);
  32         },
  33         // Optimistic update
  34         onMutate: async (newFeatureData) => {
