  41                         ? { ...feature, ...newFeatureData.payload }
  42                         : feature
  43                 ) || []
  44             );
  45 
  46             return { previousFeatures };
  47         },
  48         onError: (err: any, variables, context) => {
  49             if (context?.previousFeatures) {
  50                 queryClient.setQueryData(featureKeys.lists(), context.previousFeatures);
  51             }
  52             toast({
  53                 title: "Update Failed",
  54                 description: err.message || "Could not update the feature.",
